const meta = {
  component: ButtonGroup,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nGroup related buttons with consistent styling.\n\n**Import:** `@/registry/erbium/ui/button-group`\n\n## Usage\n\n```tsx\nimport {\n  ButtonGroup,\n  ButtonGroupSeparator,\n  ButtonGroupText,\n} from \"@/registry/erbium/ui/button-group\";\n```\n\n```tsx\n<ButtonGroup>\n  <Button>Button 1</Button>\n  <Button>Button 2</Button>\n</ButtonGroup>\n```\n\n## Composition\n\nUse the following composition to build a `ButtonGroup`:\n\n```text\nButtonGroup\n├── Button or Input\n├── ButtonGroupSeparator\n└── ButtonGroupText\n```\n\n## Accessibility\n\n- The `ButtonGroup` component has the `role` attribute set to `group`.\n\n- Use <Kbd hotkey=\"Tab\" /> to navigate between the buttons in the group.\n\n- Use `aria-label` or `aria-labelledby` to label the button group.\n\n```tsx\n<ButtonGroup aria-label=\"Button group\">\n  <Button>Button 1</Button>\n  <Button>Button 2</Button>\n</ButtonGroup>\n```\n\n## ButtonGroup vs ToggleGroup\n\n- Use the `ButtonGroup` component when you want to group buttons that perform an action.\n\n- Use the `ToggleGroup` component when you want to group buttons that toggle a state.\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [mergeProps](https://base-ui.com/react/utils/merge-props)\n- [useRender](https://base-ui.com/react/utils/use-render)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof ButtonGroup>;

export default { ...meta, title: "Components/Button Group",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

