import { Icon } from "@/registry/erbium/ui/icon";

import { RotatingChevron } from "@/registry/erbium/ui/stateful-icon";
import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import {
  Popover,
  PopoverContent,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/registry/erbium/ui/popover";
import { Separator } from "@/registry/erbium/ui/separator";
import { Textarea } from "@/registry/erbium/ui/textarea";

const ButtonGroupPopover = () => (
  <ButtonGroup>
    <Button variant="outline">
      <Icon name="bot" /> Copilot
    </Button>
    <Popover>
      <PopoverTrigger
        render={
          <Button
            variant="outline"
            size="icon"
            aria-label="Open Popover"
            className="group group/popover-trigger"
          >
            <RotatingChevron />
          </Button>
        }
      />
      <PopoverContent align="end" className="overflow-hidden rounded-xl">
        <PopoverHeader>
          <PopoverTitle>Agent Tasks</PopoverTitle>
        </PopoverHeader>
        <Separator />
        <div className="flex flex-col gap-related text-caption">
          <Textarea placeholder="Describe your task in natural language." className="resize-none" />
          <p className="font-medium">Start a new task with Copilot</p>
          <p className="text-muted-foreground">
            Describe your task in natural language. Copilot will work in the background and open a
            pull request for your review.
          </p>
        </div>
      </PopoverContent>
    </Popover>
  </ButtonGroup>
);

export default ButtonGroupPopover;

import * as React from "react";
import { Icon } from "@/registry/erbium/ui/icon";

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import {
  NumberField,
  NumberFieldGroup,
  NumberFieldInput,
} from "@/registry/erbium/ui/number-field";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@/registry/erbium/ui/select";

const CURRENCIES = [
  {
    label: "US Dollar",
    value: "$",
  },
  {
    label: "Euro",
    value: "€",
  },
  {
    label: "British Pound",
    value: "£",
  },
];

const ButtonGroupSelect = () => {
  const [currency, setCurrency] = React.useState("$");

  return (
    <ButtonGroup>
      <ButtonGroup>
        <Select
          value={currency}
          onValueChange={(value) => {
            setCurrency(value ?? "$");
          }}
        >
          <SelectTrigger className="font-mono">{currency}</SelectTrigger>
          <SelectContent className="min-w-24">
            {CURRENCIES.map((currency) => (
              <SelectItem key={currency.value} value={currency.value}>
                {currency.value} <span className="text-muted-foreground">{currency.label}</span>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <NumberField
          className="w-36"
          format={{ maximumFractionDigits: 2, minimumFractionDigits: 2 }}
        >
          <NumberFieldGroup className="rounded-s-none">
            <NumberFieldInput aria-label="Amount" placeholder="10.00" />
          </NumberFieldGroup>
        </NumberField>
      </ButtonGroup>
      <ButtonGroup>
        <Button aria-label="Send" size="icon" variant="outline">
          <Icon name="arrow-right-01" />
        </Button>
      </ButtonGroup>
    </ButtonGroup>
  );
};

export default ButtonGroupSelect;

